import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";
import { supabasePublicKey, supabaseUrl } from "@/lib/config";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * One-time sign-in hand-off. Either path works:
 *   ?code=...             PKCE code from a real magic-link email
 *   ?token_hash=...&type= token hash generated by the server-side sign-in route
 *
 * The session is written to HttpOnly cookies; the browser never sees the token
 * after this redirect completes.
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  const tokenHash = url.searchParams.get("token_hash");
  const type = url.searchParams.get("type") ?? "magiclink";
  const next = url.searchParams.get("next") ?? "/admin";

  const cookieStore = await cookies();
  const supabase = createServerClient(supabaseUrl, supabasePublicKey, {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet, headers) {
        for (const { name, value, options } of cookiesToSet) {
          cookieStore.set(name, value, options);
        }
        for (const [key, value] of Object.entries(headers ?? {})) {
          if (key.toLowerCase() === "set-cookie") continue;
          cookieStore.set(key, value);
        }
      },
    },
  });

  let failed = false;
  if (code) {
    const { error } = await supabase.auth.exchangeCodeForSession(code);
    failed = Boolean(error);
  } else if (tokenHash) {
    const { error } = await supabase.auth.verifyOtp({
      type: type as "magiclink" | "email",
      token_hash: tokenHash,
    });
    failed = Boolean(error);
  } else {
    failed = true;
  }

  if (failed) {
    const target = new URL("/admin/login", url.origin);
    target.searchParams.set("error", "expired");
    return NextResponse.redirect(target);
  }

  const target = new URL(next.startsWith("/") ? next : "/admin", url.origin);
  return NextResponse.redirect(target);
}
